  ('mod_simma_under_01', 'mod', 8, 9, 2, 'Simma under vattnet', 'Simma en bit under vattnet med öppna ögon eller simglasögon', '🐬', 'Börja med att hämta saker från botten i grunt vatten med en vuxen nära.', false, array['vatten', 'simning']::text[], true, 'star', false),
  ('mod_teater_01', 'mod', 8, 9, 2, 'Spela teater', 'Vara med i en teaterpjäs hemma eller i skolan', '🎭', 'Hjälp till med repliker och kostym. Publiken ska jubla!', false, array['scen', 'kreativitet']::text[], true, 'star', false),
  ('mod_ny_aktivitet_01', 'mod', 10, 13, 2, 'Prova en ny aktivitet eller sport', 'Prova en ny aktivitet eller sport', '🏄', 'Det är modigt att vara nybörjare. Prata om det!', false, array['nytt', 'rörelse']::text[], false, 'star', false),
  ('mod_presentation_01', 'mod', 10, 13, 2, 'Hålla en kort presentation för familjen', 'Hålla en kort presentation för familjen', '🎙️', 'Låt barnet välja ämne helt själv och ge publiken uppgiften att ställa en fråga.', false, array['scen', 'tala']::text[], false, 'star', false),
  ('mod_lager_01', 'mod', 10, 13, 3, 'Åka på läger', 'Åka på läger eller övernattning med en förening', '⛺', 'Packa tillsammans och prata om hur man gör om man längtar hem.', false, array['nytt', 'trygghet']::text[], true, 'star', false),
  ('mod_upptrada_01', 'mod', 10, 13, 3, 'Uppträda inför publik', 'Uppträda inför publik, till exempel på en skolavslutning', '🎭', 'Öva många gånger hemma och fira efteråt oavsett hur det gick.', false, array['scen', 'mod']::text[], true, 'star', false),
  ('mod_hopptorn_01', 'mod', 10, 13, 3, 'Hoppa från hopptornet', 'Hoppa från ett hopptorn i simhallen', '🤸', 'Börja från en låg höjd och hoppa bara när badvakten är på plats. Inget tvång.', false, array['vatten', 'mod']::text[], true, 'star', false),
  ('mod_prata_med_ny_01', 'mod', 10, 13, 2, 'Prata med någon ny i skolan', 'Ta kontakt med någon ny i skolan', '👋', 'Prata om enkla sätt att börja: fråga om något ni båda gillar.', false, array['vänskap', 'mod']::text[], true, 'star', false),
  ('mod_lara_nytt_01', 'mod', 10, 13, 2, 'Lära mig något nytt själv', 'Lära sig något nytt själv med instruktioner eller film', '🎸', 'Fråga vad barnet vill lära sig och hjälp till att hitta material.', false, array['lärande', 'uthållighet']::text[], true, 'star', false),
  ('mod_ny_ratt_01', 'mod', 10, 13, 1, 'Beställa en rätt jag aldrig har ätit', 'Beställa och smaka en rätt man aldrig har ätit, på restaurang', '🍜', 'Välj en restaurang med ett annat kök och låt barnet välja helt själv.', false, array['mat', 'nytt']::text[], true, 'star', false),
  ('mod_visa_skapelse_01', 'mod', 10, 13, 2, 'Visa något jag har skapat', 'Visa upp något man har skapat, till exempel en teckning, film eller berättelse', '🖼️', 'Fråga hur barnet vill ha respons och börja med det som är bra.', false, array['kreativitet', 'mod']::text[], true, 'star', false),
  ('mod_soka_lag_01', 'mod', 10, 13, 2, 'Söka till ett lag eller en kurs', 'Söka eller provspela till ett lag, en kör eller en kurs', '📝', 'Prata om att det är modigt att försöka, oavsett vad det blir.', false, array['nytt', 'mod']::text[], true, 'star', false),
  ('mod_trick_01', 'mod', 10, 13, 2, 'Lära mig ett trick', 'Öva in ett nytt trick på skateboard, kickbike eller cykel', '🛹', 'Hjälm och skydd på. Filma framstegen så syns hur mycket barnet har lärt sig.', false, array['motorik', 'uthållighet']::text[], true, 'star', false),
  ('mod_snorkla_01', 'mod', 10, 13, 2, 'Snorkla', 'Snorkla i grunt vatten och titta på livet under ytan', '🤿', 'Öva i simhallen först. En vuxen är alltid med i vattnet.', false, array['vatten', 'natur']::text[], true, 'star', false),
  ('mod_initiativ_01', 'mod', 10, 13, 1, 'Ta initiativ till en aktivitet', 'Ta initiativ och föreslå en aktivitet för kompisgänget', '📣', 'Det är modigt att vara den som föreslår. Prata om vad man gör om ingen nappar.', false, array['socialt', 'initiativ']::text[], true, 'star', false),
  ('mod_skidlift_01', 'mod', 10, 13, 2, 'Åka skidlift själv', 'Åka ankarlift eller stolslift själv', '🚡', 'Åk tillsammans först och gå igenom hur man går av.', false, array['vinter', 'självständighet']::text[], true, 'star', false),
  ('mod_asikt_i_grupp_01', 'mod', 11, 13, 2, 'Säga min åsikt i en grupp', 'Säga sin åsikt i en grupp, till exempel i klassrådet', '🗣️', 'Beröm modet att säga något, oavsett vad gruppen tycker.', false, array['tala', 'mod']::text[], true, 'star', false),
  ('mod_berg_01', 'mod', 11, 13, 3, 'Vandra upp på ett berg', 'Vandra upp på ett berg eller en hög utsiktspunkt', '⛰️', 'Planera turen tillsammans med pauser och matsäck. Vänd om vädret slår om.', false, array['friluftsliv', 'uthållighet']::text[], true, 'star', false),
  ('mod_oppet_vatten_01', 'mod', 11, 13, 3, 'Simma i öppet vatten', 'Simma en längre sträcka i sjö eller hav med en vuxen i närheten', '🌊', 'Välj en badplats med livräddning och simma längs stranden.', false, array['vatten', 'simning']::text[], true, 'star', false),
  ('mod_ny_stil_01', 'mod', 11, 13, 1, 'Prova en ny stil', 'Våga prova en ny klädstil eller frisyr', '🧢', 'Stötta barnets val även om det inte är din smak.', false, array['stil', 'självkänsla']::text[], true, 'star', false),
  ('mod_skarmfri_helg_01', 'mod', 11, 13, 2, 'Vara utan skärm en helg', 'Prova att vara utan mobil och skärm en hel helg', '📵', 'Gör det tillsammans som familj och planera roliga saker att göra i stället.', true, array['skärm', 'utmaning']::text[], true, 'star', false),
  ('mod_annat_sprak_01', 'mod', 11, 13, 2, 'Prata ett annat språk med någon', 'Prata engelska eller ett annat språk med någon på riktigt, till exempel på semestern', '🗣️', 'Det räcker att göra sig förstådd. Ingen behöver prata perfekt.', false, array['språk', 'mod']::text[], true, 'star', false),
  ('mod_ny_skola_01', 'mod', 11, 13, 2, 'Börja i en ny skola eller klass', 'Klara starten i en ny skola, klass eller grupp', '🏫', 'Besök skolan innan, gå vägen dit och prata om vad som kan kännas pirrigt.', false, array['nytt', 'trygghet']::text[], true, 'star', false)
